function makePgLogo(w, h) {
  const r = figma.createRectangle();
  r.name = 'Logo PG';
  r.resize(w, h || Math.round(w * 0.78));
  r.fills = [{ type: 'IMAGE', imageHash: PG_HASH, scaleMode: 'FIT' }];
  return r;
}

function b64ToBytes(b64) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup = new Uint8Array(128);
  for (let i = 0; i < chars.length; i++) lookup[chars.charCodeAt(i)] = i;
  let len = b64.length, pad = 0;
  if (b64[len - 1] === '=') pad++;
  if (b64[len - 2] === '=') pad++;
  const out = new Uint8Array((len * 3) / 4 - pad);
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const a = lookup[b64.charCodeAt(i)], b = lookup[b64.charCodeAt(i + 1)];
    const c = lookup[b64.charCodeAt(i + 2)], d = lookup[b64.charCodeAt(i + 3)];
    out[p++] = (a << 2) | (b >> 4);
    if (p < out.length) out[p++] = ((b & 15) << 4) | (c >> 2);
    if (p < out.length) out[p++] = ((c & 3) << 6) | d;
  }
  return out;
}

const hex = (h) => ({
  r: parseInt(h.slice(1, 3), 16) / 255,
  g: parseInt(h.slice(3, 5), 16) / 255,
  b: parseInt(h.slice(5, 7), 16) / 255,
});
const solid = (h, op) => ({ type: 'SOLID', color: hex(h), opacity: op === undefined ? 1 : op });
const grad = (c1, c2) => ({
  type: 'GRADIENT_LINEAR',
  gradientTransform: [[1, 0, 0], [0, 1, 0]],
  gradientStops: [
    { position: 0, color: Object.assign({}, hex(c1), { a: 1 }) },
    { position: 1, color: Object.assign({}, hex(c2), { a: 1 }) },
  ],
});
const shadow = (h, a, y, r) => [{ type: 'DROP_SHADOW', color: Object.assign({}, hex(h), { a: a }), offset: { x: 0, y: y }, radius: r, spread: 0, visible: true, blendMode: 'NORMAL' }];

function makeSvg(svgStr, w, h) {
  const n = figma.createNodeFromSvg(svgStr);
  if (w) n.resize(w, h || w);
  return n;
}

function makeText(str, size, weight, color, opts) {
  opts = opts || {};
  const t = figma.createText();
  t.fontName = { family: 'Plus Jakarta Sans', style: weight };
  t.fontSize = size;
  t.characters = str;
  t.fills = [solid(color, opts.op !== undefined ? opts.op : 1)];
  if (opts.align) t.textAlignHorizontal = opts.align;
  if (opts.lh) t.lineHeight = { unit: 'PIXELS', value: opts.lh };
  if (opts.w) { t.textAutoResize = 'HEIGHT'; t.resize(opts.w, 20); }
  return t;
}

function mkAL(dir, opts) {
  opts = opts || {};
  const f = figma.createFrame();
  f.layoutMode = dir;
  f.primaryAxisSizingMode = 'AUTO';
  f.counterAxisSizingMode = 'AUTO';
  f.fills = [];
  if (opts.name) f.name = opts.name;
  if (opts.gap !== undefined) f.itemSpacing = opts.gap;
  if (opts.p !== undefined) { f.paddingLeft = opts.p; f.paddingRight = opts.p; f.paddingTop = opts.p; f.paddingBottom = opts.p; }
  if (opts.px !== undefined) { f.paddingLeft = opts.px; f.paddingRight = opts.px; }
  if (opts.py !== undefined) { f.paddingTop = opts.py; f.paddingBottom = opts.py; }
  if (opts.pl !== undefined) f.paddingLeft = opts.pl;
  if (opts.pr !== undefined) f.paddingRight = opts.pr;
  if (opts.pt !== undefined) f.paddingTop = opts.pt;
  if (opts.pb !== undefined) f.paddingBottom = opts.pb;
  if (opts.main) f.primaryAxisAlignItems = opts.main;
  if (opts.cross) f.counterAxisAlignItems = opts.cross;
  if (opts.r !== undefined) f.cornerRadius = opts.r;
  if (opts.bg) f.fills = [solid(opts.bg, opts.bgOp !== undefined ? opts.bgOp : 1)];
  if (opts.grad) f.fills = [grad(opts.grad[0], opts.grad[1])];
  if (opts.border) { f.strokes = [solid(opts.border, opts.borderOp !== undefined ? opts.borderOp : 1)]; f.strokeWeight = opts.bw || 1; }
  return f;
}

function icSvg(paths, color, size) {
  return makeSvg('<svg width="' + (size || 20) + '" height="' + (size || 20) + '" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">' + paths.split('CUR').join(color || '#0F172A') + '</svg>', size || 20);
}

