  seg.appendChild(t1); t1.layoutSizingHorizontal = 'FILL';
  const t2 = mkAL('HORIZONTAL', { gap: 8, py: 11, main: 'CENTER', cross: 'CENTER', r: 20, grad: ['#00BFA5', '#1E88E5'] });
