  gpn.appendChild(makeText('GPN / BI', 11, 'ExtraBold', '#FFFFFF')); strip.appendChild(gpn);

  const qb = mkAL('VERTICAL', { gap: 14, px: 24, pt: 22, pb: 26, cross: 'CENTER' });
  card.appendChild(qb); qb.layoutSizingHorizontal = 'FILL';
  qb.appendChild(makeText(personName, 19, 'ExtraBold', '#0F172A'));
  qb.appendChild(makeText(phone, 13, 'Medium', '#64748B'));

  const qrBox = figma.createFrame();
  qrBox.name = 'QRIS Card'; qrBox.resize(260, 260); qrBox.cornerRadius = 18;
  qrBox.fills = [solid('#FFFFFF')]; qrBox.strokes = [solid('#E2E8F0')]; qrBox.strokeWeight = 1.2;
  qrBox.effects = shadow('#0F172A', 0.06, 4, 14);
  qb.appendChild(qrBox);
