  qrImg.name = 'QRIS Matrix Exact'; qrImg.resize(236, 236); qrImg.x = 12; qrImg.y = 12;
  qrImg.fills = [{ type: 'IMAGE', imageHash: qrHash, scaleMode: 'FIT' }];
  qrBox.appendChild(qrImg);

  const nom = mkAL('HORIZONTAL', { px: 18, py: 8, r: 16, bg: '#F1F5F9' });
  nom.appendChild(makeText('Penerima Bebas Mengisi Nominal', 12.5, 'SemiBold', '#475569'));
